 View root(){View result=null;for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.isLaidOut()&&view.getContext().getPackageName().equals(c.getPackageName())){assertNull("One focused application window",result);result=view;}return result;}
