  final class ReminderPort implements TravelTrackingReminders.Port {
   final List<TravelTrackingReminders.Request> scheduled=new CopyOnWriteArrayList<>();int shown,dismissed,cancelled;volatile boolean allowed=true,active,failDismiss;volatile Runnable afterSchedule;
   public void schedule(Context context,TravelTrackingReminders.Request request){scheduled.add(request);Runnable callback=afterSchedule;afterSchedule=null;if(callback!=null)callback.run();}
   public void cancel(Context context,TravelTrackingReminders.Request request){if(request!=null)cancelled++;}
   public void dismiss(Context context){dismissed++;if(failDismiss)throw new IllegalStateException("Private cleanup failure");active=false;}
   public boolean allowed(Context context){return allowed;}
   public void show(Context context,TravelTrackingReminders.Request request){assertEquals("Receipt committed before injected notification",request.token(),prefs.getString(TravelTrackingReminders.CONSUMED,""));assertTrue("Current fake manual owner",fake.manual);shown++;active=true;}
  }
  final class Fake implements TravelCues.Control,TravelCueSession.Clock,TravelCueSession.Scheduler {
   long wall=Instant.parse("2026-10-23T19:00:00Z").toEpochMilli(),elapsed=10000;boolean manual,alive=true,failOutput;int arms,opens,on,off,closed;final TreeMap<Long,List<Runnable>> queue=new TreeMap<>();TravelCueSession session;TravelCueSession.Events events;
   public TravelCues.Manual manual(){return manual?new TravelCues.Manual(7,"manual-fixture"):null;}
   public void arm(Context context,TravelCues.Manual expected,long revision){TravelCues.Manual current=manual();if(expected==null||current==null||expected.session!=current.session||!expected.token.equals(current.token))throw new IllegalStateException("The manual recording changed.");TravelPlan trip=repository.load(wall);TravelCuePlan plan=store.load(trip,wall);if(plan.revision!=revision||!plan.enabled)throw new IllegalStateException("Reopen the saved cue window.");if(session!=null&&session.state().busy())throw new IllegalStateException("Already armed");arms++;String nonce=UUID.randomUUID().toString();store.begin(nonce,revision);session=new TravelCueSession(nonce,plan.next(wall),this,this,event->{opens++;events=event;if(failOutput){event.lost("This phone's flashlight is unavailable.");return ()->{};}event.ready(new TravelCueSession.Handle(){public void set(boolean enabled){if(enabled)on++;else off++;}public void close(){closed++;}});return ()->{};},value->store.save(value,revision),()->alive&&manual);session.start();}
   public void stop(String nonce){if(session!=null&&session.nonce.equals(nonce))session.stop("You stopped light cues.");}
   public boolean live(String nonce){return session!=null&&session.nonce.equals(nonce)&&session.state().busy();}
   public TravelCueSession.State status(Context context){if(session!=null)return session.state();TravelCueSession.State s=store.last();return s!=null&&s.busy()?new TravelCueSession.State(s.nonce,TravelCueSession.Phase.INTERRUPTED,s.start,s.end,s.requests,s.skipped,"The previous session stopped. No pulses were replayed."):s;}
   public long wall(){return wall;}public long elapsed(){return elapsed;}public String zone(){return "Asia/Riyadh";}public void at(long at,Runnable callback){queue.computeIfAbsent(at,k->new ArrayList<>()).add(callback);}public void cancel(){queue.clear();}
   void advance(long milliseconds){long end=elapsed+milliseconds;while(!queue.isEmpty()&&queue.firstKey()<=end){long next=queue.firstKey();wall+=next-elapsed;elapsed=next;List<Runnable> callbacks=queue.remove(next);for(Runnable r:callbacks)r.run();}wall+=end-elapsed;elapsed=end;}
  }
