  trip=h.repository.load(h.fake.wall);previous=h.store.load(trip,h.fake.wall);trip.trackingReminders=false;h.repository.save(trip,previous,h.fake.wall);TravelTrackingReminders.apply(c);assertNull(TravelTrackingReminders.pending(h.repository));fireReminder(h,fresh);assertEquals(1,h.reminders.shown);assertTrue(h.reminders.cancelled>0);assertEquals("No torch admission in reminder proof",0,h.fake.arms);assertEquals(0,h.fake.opens);
