 @Test public void windowReviewCancelSaveRecreateAndReopenNeverArmAnything()throws Exception{try(Harness h=new Harness()){try{h.open(TravelActivity.class);mainFits();h.capture("settings-off");tap("Light source",true);tap("Tracking reminder settings",true);require("Active manual recording only");assertEquals(0,h.fake.arms);assertEquals(0,h.fake.opens);h.capture("tracking-settings");h.recreate();require("Active manual recording only");h.capture("tracking-settings-recreated");tap("Done",false);require("Save travel settings");Activity mainAboutOwner=current();tap("About light cues",true);require("Experimental light cues");h.recreate(mainAboutOwner);require("Experimental light cues");h.capture("about-main-recreated");tap("Got it",false);require("Save travel settings");mainFits();assertEquals(0,h.fake.arms);assertEquals(0,h.fake.opens);tap("Experimental light cues",true);require("Choose your window");h.capture("window");tap("First night",true);h.capture("date");tap("Cue date 2026-10-23",true);tap("Start time",true);h.capture("time");tap("Cancel",false);tap("Window length",true);tap("30 min",true);h.recreate();require("Choose your window");h.capture("window-recreated");tap("Use experimental cues",false);h.capture("settings-enabled");assertFalse(h.store.load(h.repository.load(h.fake.wall),h.fake.wall).enabled);tap("Save travel settings",false);assertTrue(device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return h.owned.stream().allMatch(Activity::isDestroyed);}},5000));TravelCuePlan saved=h.store.load(h.repository.load(h.fake.wall),h.fake.wall);assertTrue(saved.enabled);assertTrue(saved.reviewed);assertEquals(30,saved.minutes);assertEquals(0,h.fake.arms);h.open(TravelActivity.class);h.capture("settings-reopened");tap("Light source",true);require("Light-cue settings");h.capture("light-settings");h.recreate();require("Light-cue settings");require("Tracking reminder settings");h.capture("light-settings-recreated");Activity aboutOwner=current();tap("About experimental cues",true);require("Experimental light cues");h.recreate(aboutOwner);require("Experimental light cues");require("Your chosen window requests a brief flashlight pulse every 15 seconds. Android and your flashlight may stretch or miss requests. This is not a measured light dose or a proven jet-lag treatment. Saving settings never starts light output.");assertFalse(device.hasObject(By.text("Daylight reminder time")));assertFalse(device.hasObject(By.text("Reminder days")));h.capture("about-recreated");tap("Got it",false);require("Light-cue settings");tap("Cue window",true);tap("First night",true);tap("Cue date 2026-10-27",true);tap("Use experimental cues",false);require("Choose cue nights before your departure date.");errorAboveAction("Choose cue nights before your departure date.","Use experimental cues");h.capture("invalid-window");tap("Cancel",false);require("Light-cue settings");assertTrue(h.store.load(h.repository.load(h.fake.wall),h.fake.wall).enabled);assertEquals(0,h.fake.opens);tap("Review & arm cues",false);require("Not armed");assertEquals(0,h.fake.arms);h.capture("review-from-menu");h.finish(current());require("Light-cue settings");tap("Done",false);require("Save travel settings");assertEquals(0,h.fake.opens);trackingReminderProof(h);}catch(Throwable failure){h.diagnostic(failure);throw failure;}}}
 @Test public void explicitArmStopErrorsAndInterruptedReopenUseOnlyFakeLight()throws Exception{try(Harness h=new Harness()){h.enable();h.open(TravelCueReviewActivity.class);require("Not armed");h.capture("no-manual");i.runOnMainSync(()->h.fake.manual=true);tap("Refresh status",false);h.capture("ready");tap("Arm remaining window",false);require("Light cues active");assertEquals(1,h.fake.on);i.runOnMainSync(()->{new TravelCueStopReceiver().onReceive(c,new Intent().setAction(TravelCueStopReceiver.STOP).putExtra("nonce",UUID.randomUUID().toString()));new TravelCueStopReceiver().onReceive(c,new Intent().setAction(TravelCueStopReceiver.STOP).putExtra("nonce","not-a-nonce"));});assertTrue(h.fake.session.state().busy());h.capture("active");i.runOnMainSync(()->h.fake.advance(2));assertEquals(1,h.fake.off);h.recreate();require("Light cues active");assertEquals(1,h.fake.arms);h.capture("active-recreated");tap("Stop light cues",false);require("Light cues stopped");assertTrue(h.fake.closed>0);h.capture("stopped");h.finish(current());h.open(TravelCueReviewActivity.class);require("Light cues stopped");h.capture("stopped-reopened");i.runOnMainSync(()->h.fake.failOutput=true);tap("Arm remaining window",false);require("Light cues need attention");require("This phone's flashlight is unavailable.");errorAboveAction("This phone's flashlight is unavailable.","Arm remaining window");h.capture("output-error");assertEquals(2,h.fake.arms);h.finish(current());i.runOnMainSync(()->{String nonce=UUID.randomUUID().toString();h.fake.session=null;h.store.begin(nonce,99);h.store.save(new TravelCueSession.State(nonce,TravelCueSession.Phase.RUNNING,h.fake.wall,h.fake.wall+900000,3,0,""),99);});h.open(TravelCueReviewActivity.class);require("Session interrupted");h.capture("interrupted");assertEquals(2,h.fake.opens);assertEquals(1,h.fake.on);}}
